std::vector<Capture> run(const std::string& prefix,int gpu,bool deferred,unsigned count,bool instanced,const std::vector<SceneSnapshot>& states,bool crowded=false){Window window;RenderOptions options;options.gpu=gpu;options.width=width;options.height=height;options.samples=count;options.viewmodel_samples=4;options.deferred=deferred;options.draw_instancing=instanced;options.capture_exclusive=true;options.frames_in_flight=2;
 if(count==1){if(crowded){for(unsigned i:{0u,17u,300u,514u,777u,1000u}){auto& m=states[0].objects[i].world;auto p=projected(m[12],m[13],3);options.scene_product_probes.push_back({p[0],p[1]});}}else{for(auto v:{std::array<double,2>{-.9,.55},{-.3,.55},{.3,.55},{.81,.46},{.99,.46},{.3,-.55},{-.9,-.55},{.9,0}}){auto p=projected(v[0],v[1],3);options.scene_product_probes.push_back({p[0],p[1]});}}}
 HostedViewport view(options,states.front(),window.child);std::vector<Capture> result;unsigned sequence=0;
 for(std::size_t k=0;k<states.size();++k){need(++captures<=32&&std::chrono::steady_clock::now()-began<std::chrono::seconds(180),"Finite32capture/180s admission");auto path=output/(prefix+"-"+std::to_string(k)+".bmp");auto start=std::chrono::steady_clock::now();for(;;){pump();auto before=view.report().diagnostics.frame_execution.submitted;if(view.draw_capture(states[k],path.string()))break;need(view.report().diagnostics.frame_execution.submitted==before,"Accepted unpresented draw interrupts matched cohort");need(std::chrono::steady_clock::now()-start<std::chrono::seconds(8),"Visible capture admission timed out");std::this_thread::sleep_for(std::chrono::milliseconds(1));}++sequence;auto report=view.report();Bitmap image(path);
  need(report.success&&report.hardware&&report.capture_written&&report.validation_errors==0&&report.samples==count&&report.width==width&&report.height==height&&report.diagnostics.deferred==deferred&&report.diagnostics.draw_instancing==instanced,"Actual native capture recipe differs");auto& f=report.diagnostics.frame_execution;need(f.submitted==sequence&&report.diagnostics.completed_submissions==sequence&&f.outstanding==0,"Original accepted submissions did not retire exactly");if(actual_gpu.empty())actual_gpu=report.gpu_name;need(!actual_gpu.empty()&&actual_gpu==report.gpu_name,"Actual GPU changed");auto d=report.diagnostics.last_draws;need(d.camera_batches<=d.camera_draws&&d.shadow_batches<=d.shadow_draws,"Batch counts exceed instance counts");if(!instanced)need(d.camera_batches==d.camera_draws&&d.shadow_batches==d.shadow_draws,"Direct reference must submit one command per visible instance/view");
  Json row={{"path",path.filename().string()},{"bytes",image.bytes.size()},{"sha256",image.digest()},{"label",prefix},{"phase",k},{"gpu",report.gpu_name},{"hardware",report.hardware},{"success",report.success},{"validation_errors",report.validation_errors},{"samples",count},{"deferred",deferred},{"instanced",instanced},{"submitted",f.submitted},{"completed",report.diagnostics.completed_submissions},{"outstanding",f.outstanding},{"counts",counts(d)},{"history_valid",report.diagnostics.scene_products.history_valid},{"history_sequence",report.diagnostics.scene_products.history_sequence},{"reset",report.diagnostics.scene_products.history_reset_reason},{"probes",samples(report)}};
  if(report.diagnostics.viewmodel){const auto& vm=*report.diagnostics.viewmodel;row["foreground"]={{"rendered",vm.rendered},{"samples",vm.samples},{"counts",counts(vm.draws)}};}
  record["captures"].push_back(std::move(row));result.push_back({std::move(image),std::move(report)});bounds(output);}
 return result;}
void equal_counts(const DrawCounts& a,const DrawCounts& b){auto x=counts(a),y=counts(b);x.erase("camera_batches");x.erase("shadow_batches");y.erase("camera_batches");y.erase("shadow_batches");need(x==y,"Object/view-instance counts changed under batching");}
void compare(const std::string& label,const Capture& a,const Capture& b){unsigned error=0;for(unsigned y=0;y<height;++y)for(unsigned x=0;x<width;++x){auto p=a.image.pixel(x,y),q=b.image.pixel(x,y);for(unsigned c=0;c<3;++c)error=std::max(error,static_cast<unsigned>(std::abs(p[c]-q[c])));}need(error==0,"Direct/instanced complete original RGB differs");need(samples(a.report)==samples(b.report),"Direct/instanced raw product probes differ");need(a.report.diagnostics.scene_products.history_valid==b.report.diagnostics.scene_products.history_valid&&a.report.diagnostics.scene_products.history_sequence==b.report.diagnostics.scene_products.history_sequence,"Direct/instanced history differs");equal_counts(a.report.diagnostics.last_draws,b.report.diagnostics.last_draws);need(bool(a.report.diagnostics.viewmodel)==bool(b.report.diagnostics.viewmodel),"Foreground presence differs");if(a.report.diagnostics.viewmodel)equal_counts(a.report.diagnostics.viewmodel->draws,b.report.diagnostics.viewmodel->draws);record["comparisons"].push_back({{"label",label},{"whole_rgb_error",error},{"all_available_raw_probes_exact",true},{"excluded_image_pixels",0}});}
void positive(const Capture& c,bool products){for(unsigned i=0;i<3;++i){auto xy=projected((double(i)-1.5)*.6,.55,3);auto color=c.image.pixel(xy[0],xy[1]);need(color[i]>color[(i+1)%3]+40&&color[i]>color[(i+2)%3]+40,"Independent known material/spatial RGB cell missing");}auto back=projected(.3,0,3);auto color=c.image.pixel(back[0],back[1]);need(color[0]>color[1]+40&&color[0]>color[2]+40,"Back-facing double-sided draw lost at pipeline break");if(products){auto& p=c.report.diagnostics.scene_products.probes;need(p.size()==8,"All selected raw product probes required");for(unsigned i:{0u,1u,2u,4u,5u,6u,7u}){need(p[i].surface_valid,"Known visible cell lacks surface");close_number(p[i].depth,40./39.9-4./39.9/(i==6?2.99:3.),3e-6,"Independent known plane depth differs");}close_number(p[3].depth,40./39.9-4./39.9/5,3e-6,"Masked hole wrote depth instead of receiver");}}
void shadow_oracle(const std::vector<Capture>& c){unsigned kept=0,holes=0,error=0;for(unsigned card=0;card<2;++card)for(unsigned y=0;y<2;++y)for(unsigned x=0;x<2;++x){double px=1.2+((x+.5)/2.-.5)*.6-1.5,py=(card==0?.4:-.4)+((y+.5)/2.-.5)*.6;auto xy=projected(px,py,4);auto lit=c[2].image.pixel(xy[0],xy[1]),opaque=c[3].image.pixel(xy[0],xy[1]),actual=c[4].image.pixel(xy[0],xy[1]);need(lit[1]>opaque[1]+12,"Independent opaque shadow control is not dark");bool solid=card==0&&(x+y)%2!=0;auto expected=solid?opaque:lit;for(unsigned k=0;k<3;++k)error=std::max(error,static_cast<unsigned>(std::abs(actual[k]-expected[k])));if(solid)++kept;else++holes;}need(kept==2&&holes==6&&error<=3,"Per-instance masked shadow factor/UV oracle differs");record["shadow_oracles"].push_back({{"kept",kept},{"holes",holes},{"max_rgb_error",error}});}
